svg.script:
(function () {

  var tip = document.getElementById("common-tooltip");
  var tipText = document.getElementById("tooltip-text");
  var tipBg = document.getElementById("tooltip-bg");

  if (!tip || !tipText || !tipBg) return;

  // 清除上一次的文字
  function clearTooltip() {
    while (tipText.firstChild) {
      tipText.removeChild(tipText.firstChild);
    }
  }

  // 顯示指定物件的說明
  function showTooltip(desc,event) {

    clearTooltip();

    var lines = desc.textContent.trim().split(/\n/);

    lines.forEach(function (line, index) {

      var tspan = document.createElementNS(
        "http://www.w3.org/2000/svg", "tspan"
      );

      tspan.setAttribute("x", "800");
      tspan.setAttribute("dy", index === 0 ? "0" : "25");
      tspan.textContent = line.trim();

      tipText.appendChild(tspan);
    });

    // 依文字行數調整背景高度
    var lineHeight = 25;
    var topPadding = 30;
    var bottomPadding = 20;

    var newHeight = lines.length * lineHeight
                  + topPadding + bottomPadding;

    tipBg.setAttribute("height", newHeight);
    // 取得滑鼠在 SVG 畫布中的座標
    var point = document.documentElement.createSVGPoint();

    point.x = event.clientX;
    point.y = event.clientY;

    var svgPoint = point.matrixTransform(
     document.documentElement.getScreenCTM().inverse()
    );

  // 設定提示框位置，稍微避開滑鼠
    var boxX = svgPoint.x + 15;
    var boxY = svgPoint.y + 15;

  // 避免提示框超出畫布右側
    var boxWidth = 420;
    if (boxX + boxWidth > 1283) {
     boxX = svgPoint.x - boxWidth - 15;
    }

  // 設定背景與文字的位置
    tipBg.setAttribute("x", boxX);
    tipBg.setAttribute("y", boxY);

    tipText.setAttribute("x", boxX + 20);
    tipText.setAttribute("y", boxY + 30);

    // 同步調整每一行文字的位置
    var tspans = tipText.querySelectorAll("tspan");

    tspans.forEach(function (tspan, index) {
      tspan.setAttribute("x", boxX + 20);
      tspan.setAttribute("dy", index === 0 ? "0" : "25");
   });


    tip.setAttribute("visibility", "visible");
  }

  // 找出七種材質的超連結物件
  var items = document.querySelectorAll("a");

  items.forEach(function (item) {

    // 讀取該物件內的 desc
    var desc = item.querySelector("desc");

    if (!desc) return;

    item.addEventListener("mouseenter", function (event) {
      showTooltip(desc,event);
    });

    item.addEventListener("mouseleave", function () {
      tip.setAttribute("visibility", "hidden");
    });

  });

})();
